import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { LoginRequest, LoginResponse, LoginService } from './login.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  username: string = '';
  password: string = '';
  errorMessage: string = '';
  roles: string[] = [];

  constructor(public loginService: LoginService, private router: Router) { }

  onLogin(): void {
    const request: LoginRequest = { username: this.username, password: this.password };
    this.loginService.login(request).subscribe({
      next: (response: LoginResponse) => {
        this.roles = response.roles || [];
        this.router.navigate(['/']);
      },
      error: (err) => {
        this.errorMessage = err.error?.Message || 'Login failed';
      }
    });
  }
}
<div class="login-container">
  <h2>Login</h2>
  <form (ngSubmit)="onLogin()" class="login-form">
    <div>
      <label for="username">Username:</label>
      <input type="text" id="username" [(ngModel)]="username" name="username" required>
    </div>
    <div>
      <label for="password">Password:</label>
      <input type="password" id="password" [(ngModel)]="password" name="password" required>
    </div>
    <button type="submit" class="login-btn">Login</button>
    <div *ngIf="errorMessage" class="error">{{ errorMessage }}</div>
  </form>
  <div *ngIf="loginService.isLoggedIn() | async" class="success">
    Success! You are logged in as {{ loginService.getUsername() | async }}.
    <div *ngIf="roles?.length">Roles: {{ roles.join(', ') }}</div>
  </div>
  <p class="forgot-password-link mt-4 text-center text-gray-600">
    <a [routerLink]="['/forgot-password']" class="text-blue-600 hover:text-blue-800 hover:underline">Forgot Password?</a>
  </p>
  <p class="register-link text-center mt-4 text-gray-600">
    Don't have an account? <a [routerLink]="['/register']" class="text-blue hover:text-blue-800 hover:underline">Register</a>
  </p>
</div>
